//! Golden tests: every output must equal the reference tool's (ekko-stt 0.1.2,
//! onnxruntime 1.29.0, tokenizers 0.22.2) byte for byte. The golden set is
//! generated by models/ekko-pnc/generate_golden.py.
//!
//! The model folder comes from WT_EKKO_PNC_DIR (fill it with
//! models/ekko-pnc/download.sh <dir>). Without it, the model tests print a
//! notice and pass without running.

use std::path::{Path, PathBuf};

use serde::Deserialize;
use sha2::{Digest, Sha256};

#[derive(Deserialize)]
struct Golden {
    model: ModelInfo,
    options: Opts,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct ModelInfo {
    files: std::collections::BTreeMap<String, String>,
}

#[derive(Deserialize)]
struct Opts {
    max_length: usize,
    overlap_words: usize,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    input: String,
    output: String,
    tokens: usize,
}

fn golden() -> Golden {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../models/ekko-pnc/golden.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&text).expect("golden.json parses")
}

fn model_dir() -> Option<PathBuf> {
    match std::env::var_os("WT_EKKO_PNC_DIR") {
        Some(dir) if Path::new(&dir).join(ekko_pnc::MODEL_FILE).is_file() => Some(dir.into()),
        Some(dir) => {
            eprintln!(
                "SKIPPED: WT_EKKO_PNC_DIR={} has no {}; run models/ekko-pnc/download.sh <dir>",
                Path::new(&dir).display(),
                ekko_pnc::MODEL_FILE
            );
            None
        }
        None => {
            eprintln!(
                "SKIPPED: set WT_EKKO_PNC_DIR to a folder with the Ekko PnC files \
                 (models/ekko-pnc/download.sh <dir>) to run the golden tests"
            );
            None
        }
    }
}

#[test]
fn golden_set_covers_the_required_cases() {
    let g = golden();
    assert!(
        g.cases.len() >= 40,
        "at least 40 golden inputs, got {}",
        g.cases.len()
    );
    let long = g
        .cases
        .iter()
        .filter(|c| c.tokens > g.options.max_length)
        .count();
    assert!(
        long >= 3,
        "several inputs must exceed one {}-token window, got {long}",
        g.options.max_length
    );
    assert_eq!((g.options.max_length, g.options.overlap_words), (128, 12));
}

#[test]
fn model_files_match_the_golden_checksums() {
    let Some(dir) = model_dir() else { return };
    for (name, expected) in golden().model.files {
        let bytes = std::fs::read(dir.join(&name)).unwrap_or_else(|e| panic!("{name}: {e}"));
        let actual: String = Sha256::digest(&bytes)
            .iter()
            .map(|b| format!("{b:02x}"))
            .collect();
        assert_eq!(
            actual, expected,
            "{name} differs from the file the golden set was made with"
        );
    }
}

#[test]
fn reproduces_the_reference_on_every_golden_input() {
    let Some(dir) = model_dir() else { return };
    let g = golden();
    let pnc = ekko_pnc::Punctuator::from_dir(&dir).expect("load Ekko PnC");
    let mut failures = Vec::new();
    for case in &g.cases {
        let got = pnc.punctuate(&case.input).expect("punctuate");
        if got != case.output {
            failures.push(format!(
                "{}:\n  expected: {:?}\n  got:      {:?}",
                case.name, case.output, got
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} golden cases differ:\n{}",
        failures.len(),
        g.cases.len(),
        failures.join("\n")
    );
}

#[test]
fn is_usable_from_several_threads() {
    let Some(dir) = model_dir() else { return };
    let g = golden();
    let pnc = std::sync::Arc::new(ekko_pnc::Punctuator::from_dir(&dir).expect("load"));
    let handles: Vec<_> = g
        .cases
        .iter()
        .take(4)
        .map(|c| {
            let (pnc, input, output) = (pnc.clone(), c.input.clone(), c.output.clone());
            std::thread::spawn(move || assert_eq!(pnc.punctuate(&input).unwrap(), output))
        })
        .collect();
    for h in handles {
        h.join().unwrap();
    }
}
